class Trie {
  constructor() {
    this.children = {};
    this.isEnd = false;
  }

  insert(word) {
    let node = this;
    for (const ch of word) {
      if (!node.children[ch]) {
        node.children[ch] = new Trie();
      }
      node = node.children[ch];
    }
    node.isEnd = true;
  }

  search(word) {
    const node = this._traverse(word);
    return node !== null && node.isEnd === true;
  }

  startsWith(prefix) {
    return this._traverse(prefix) !== null;
  }

  _traverse(word) {
    let node = this;
    for (const ch of word) {
      if (!node.children[ch]) return null;
      node = node.children[ch];
    }
    return node;
  }
}

