function trieJudge(ops, argsList) {
  const results = [];
  let obj = null;
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const opArgs = argsList[i];
    if (op === "Trie") {
      obj = new Trie();
      results.push(null);
    } else if (op === "insert") {
      obj.insert(opArgs[0]);
      results.push(null);
    } else if (op === "search") {
      results.push(obj.search(opArgs[0]));
    } else if (op === "startsWith") {
      results.push(obj.startsWith(opArgs[0]));
    }
  }
  return results;
}

